package main

func addDashboardHistorySchema(result map[string]any, routes map[string][]string) {
	routes["GET"] = append(routes["GET"], "/api/dashboards/uid/{uid}/versions", "/api/dashboards/uid/{uid}/versions/{version}", "/api/v1/dashboard-versions/{id}", "/api/v1/dashboard-versions/{id}/{version}", "/api/v1/dashboard-version-exports/{id}/{version}", "/apis/dashboard.grafana.app/{version}/namespaces/default/dashboards?labelSelector=grafana.app/get-history=true&fieldSelector=metadata.name=UID")
	routes["POST"] = append(routes["POST"], "/api/dashboards/uid/{uid}/restore", "/api/v1/dashboard-restore/{id}", "/api/v1/dashboard-compare/{id}")
	result["commands"] = append(result["commands"].([]string), "dashboards history --id ID [--limit 10 --offset 0 --continue-token TOKEN]", "dashboards version --id ID --dashboard-version NUMBER", "dashboards version-export --id ID --dashboard-version NUMBER [--format native|grafana]", "dashboards compare --id ID --base-version NUMBER --new-version NUMBER", "dashboards restore --id ID --dashboard-version NUMBER [--revision UPDATED_AT --message TEXT]", "dashboards save --file FILE|- [--id ID --revision UPDATED_AT --message TEXT]")
	result["dashboard_history"] = map[string]any{"storage": "immutable native settings and original Classic/V1/V2 source in the same SQLite transaction as each successful save; retained after restart for both metric backends", "migration": "existing databases capture only their current known version; prior unavailable history is not invented", "pagination": "newest first, limit 1–1000; start/offset apply to first page; opaque continueToken anchors the version range", "restore": "new canonical version with parentVersion/restoredFrom; current native/numeric ID, UID, folder and plugin metadata preserved; current library models resolved without modifying shared entities; stale and identical restores do not write", "precision": "native metadata supplies string versionKey/currentVersionKey; exports and comparison before/after retain raw JSON number values", "save_message": "Grafana save message or CLI --message, at most 500 Unicode characters", "resources": "history-selector collection GET for official UnifiedDashboardAPI dual V1/V2 streams; original spec and explicit conversion.failed state for unmatched schemas; 16 MiB response budget", "pending": []string{"full App Platform dashboard resource CRUD and schema migration", "configurable dashboard version retention"}}
}
